style.css:
@-moz-document domain("youtube.com"), domain("www.youtube.com"), domain("m.youtube.com") {
/* ===== GLOBAL BASE ===== */
html, body{
  background:#0d0d0d !important;
  color:#e0e0e0 !important;
  font-family:"Fira Code", monospace !important;
  letter-spacing:.23px;
  overflow-x:hidden;
}

/* ===== WALLPAPER (single layer) ===== */
ytd-app::after{
  content:"";
  position:fixed; inset:0; z-index:-3;
  background:url("https://4kwallpapers.com/images/walls/thumbs_3t/12111.png") center/cover no-repeat fixed;
  opacity:.08; filter:saturate(.7) contrast(.8) brightness(.9);
}
/* remove extra fixed layers */
.ytd-two-column-browse-results-renderer > #contents,
#columns{ background:none !important; }

/* ===== LINKS / TEXT ===== */
a, .yt-simple-endpoint, yt-formatted-string a{
  color:#ffffff !important; text-decoration:none !important;
  transition:color .2s, text-shadow .2s;
}
a:hover, .yt-simple-endpoint:hover{
  color:#cccccc !important; text-shadow:0 0 5px rgba(255,255,255,.25);
}
#channel-name a, ytd-channel-name a,
ytd-video-owner-renderer a, ytd-video-owner-renderer #channel-name,
ytd-comment-renderer #author-text a,
ytd-comment-renderer #author-text yt-formatted-string{
  color:#ffffff !important; text-shadow:none !important;
}
#content-text{ color:#ffffff !important; text-shadow:none !important; border:none !important; }

/* ===== SEARCH ===== */
input[type="text"], input[type="password"], #search, ytd-searchbox input{
  color:#ff4d4d !important; background:transparent !important;
}
ytd-searchbox input:focus{
  border-color:#ff1a1a !important; box-shadow:0 0 8px #ff1a1a !important; outline:none !important;
}
input[type="search"]::-webkit-search-cancel-button{
  -webkit-appearance:none; appearance:none; height:16px; width:16px;
  background:none; opacity:0; cursor:pointer;
}

/* ===== PLAYER CONTROLS (lean) ===== */
.ytp-rounded-skin .ytp-chrome-controls .ytp-button,
.ytp-rounded-skin .ytp-time-display,
.ytp-rounded-skin .ytp-volume-panel,
.ytp-volume-area{
  background:transparent !important; border:none !important; box-shadow:none !important; outline:none !important;
}
.ytp-button svg, .ytp-time-display svg, .ytp-volume-area svg{ fill:currentColor !important; }

/* previews: allow logic, block overlay hit-testing only */
#movie_player .ytp-tooltip,
#movie_player .ytp-tooltip-image,
#movie_player .ytp-inline-preview,
#movie_player .ytp-inline-preview-scrim{
  pointer-events: none !important;
}
/* visual skin only */
#movie_player .ytp-tooltip{
  background: rgba(18,18,18,.9) !important; border-radius: 4px !important; color: #fff !important;
}

/* ===== MASTHEAD / FOOTER ===== */
ytd-masthead#masthead, #header.ytd-app{
  background:#1a1a1a !important; border-bottom:2px solid #990000 !important;
  box-shadow:0 0 15px rgba(255,0,0,.2) !important; text-align:center;
}
.footer, ytd-page-footer-renderer{
  background:#1a1a1a !important; border-top:2px solid #990000 !important;
  color:#ff4d4d !important; font-size:12px; padding:5px 0; text-align:center;
}

/* optional title flicker */
@keyframes flicker { 0%,100%{opacity:1;} 50%{opacity:.9;} }
ytd-masthead h1{
  color:#ff1a1a; font-size:28px; margin:0; text-shadow:0 0 5px #ff4d4d; animation:flicker 3s infinite;
}

/* ===== GUIDE BG ===== */
#guide-content{ position:relative !important; background:transparent !important; overflow:visible !important; }
#guide-content::before{
  content:""; position:fixed; top:0; left:0; width:235px; height:100vh;
  background:url("https://4kwallpapers.com/images/walls/thumbs_3t/12111.png") left center / cover no-repeat;
  opacity:.45; pointer-events:none; z-index:-1;
}
@media (max-width:1320px){ #guide-content::before{ width:72px; opacity:.4; } }
tp-yt-app-drawer#guide #guide-content::before{
  content:""; position:fixed; top:0; left:0; width:235px; height:100vh;
  background:url("https://4kwallpapers.com/images/walls/thumbs_3t/12111.png") left center / cover no-repeat;
  opacity:.45; pointer-events:none; z-index:-1;
}
#guide, #contentContainer, ytd-guide-renderer, tp-yt-app-drawer#guide{ background:transparent !important; }

/* ===== CARDS / BUTTONS ===== */
ytd-rich-grid-media, ytd-video-renderer, ytd-compact-video-renderer,
ytd-rich-item-renderer, ytd-rich-grid-row{
  background:transparent !important; border:none !important; box-shadow:none !important; outline:none !important;
}
button, .yt-spec-button-shape-next--mono{
  background:transparent; border:1px solid #1a1a1a !important; border-radius:6px;
  color:#cccccc !important; font-size:12px !important; font-weight:500 !important;
  padding:5px 10px !important; transition:background .15s, color .15s;
}
button:hover, .yt-spec-button-shape-next--mono:hover{ background:#1a1a1a !important; color:#e0e0e0 !important; }
.card, ytd-comment-thread-renderer, ytd-post-renderer[uses-compact-lockup]{
  background:#1a1a1a !important; border:1px solid rgba(255,255,255,.125) !important; border-radius:6px;
  box-shadow:0 0 8px rgba(255,255,255,.2); color:#e0e0e0 !important; margin:5px 0; padding:10px;
  transition:transform .2s, box-shadow .2s;
}
.card:hover, ytd-comment-thread-renderer:hover{
  transform:translateY(-3px); box-shadow:0 0 15px rgba(255,0,0,.35);
}

/* ===== COMMENT INPUT ===== */
#contenteditable-root[contenteditable="true"],
ytd-comment-simplebox-renderer[is-reply] #contenteditable-root[contenteditable="true"]{
  background:transparent !important; border:1px solid transparent !important; box-shadow:none !important;
  color:#ffffff !important; transition:border .2s, box-shadow .2s;
}
#contenteditable-root[contenteditable="true"]:focus,
#contenteditable-root[contenteditable="true"]:active,
ytd-comment-simplebox-renderer[is-reply] #contenteditable-root[contenteditable="true"]{
  border-color:#ff1a1a !important; box-shadow:0 0 8px #ff1a1a !important; color:#ff4d4d !important; outline:none !important;
}

/* ===== SCROLLBAR ===== */
*{ scrollbar-width:thin; scrollbar-color:#ff1a1a transparent; }
::-webkit-scrollbar{ width:10px; }
::-webkit-scrollbar-thumb{
  background:linear-gradient(rgba(0,0,0,0) 0%, #ff1a1a 100%); border-radius:10px;
}

/* ===== VERIFIED BADGE ===== */
ytd-comment-renderer #author-badges ytd-author-comment-badge-renderer{
  display:inline-flex !important; align-items:center !important;
  background:rgba(120,0,0,.6) !important; border:1px solid rgba(255,0,0,.4) !important;
  border-radius:4px !important; padding:2px 6px !important; box-shadow:0 0 6px rgba(255,0,0,.25) !important;
}
ytd-comment-renderer #author-badges ytd-author-comment-badge-renderer yt-formatted-string{
  color:#ffffff !important; font-weight:600 !important;
}
ytd-comment-renderer #author-badges ytd-author-comment-badge-renderer svg{
  fill:#ffffff !important; opacity:.9 !important;
}
ytd-author-comment-badge-renderer.style-scope.ytd-comment-view-model{
  background:rgba(90,0,0,.7) !important; border:1px solid rgba(255,0,0,.4) !important; border-radius:4px !important;
  box-shadow:0 0 6px rgba(255,0,0,.25) !important; padding:2px 6px !important; display:inline-flex !important; align-items:center !important;
}
ytd-author-comment-badge-renderer.style-scope.ytd-comment-view-model #channel-name,
ytd-author-comment-badge-renderer.style-scope.ytd-comment-view-model yt-formatted-string{
  color:#ffffff !important; text-shadow:none !important;
}
ytd-author-comment-badge-renderer.style-scope.ytd-comment-view-model svg{
  fill:#ffffff !important; opacity:.9 !important;
}

/* ===== LEFT MENU BG ===== */
#guide-inner-content{ position:relative !important; background:transparent !important; }
#guide-inner-content::before{
  content:""; position:fixed; top:0; left:0; width:235px; height:100vh;
  background:url("https://4kwallpapers.com/images/walls/thumbs_3t/12111.png") center/cover no-repeat;
  opacity:.5; pointer-events:none; z-index:-1;
}
}
